insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('noschmoakd-soffal', 'Noschmoakd-Soffal', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Naschmarkt-Sopherl', '[{"kategorie": "wörtlich", "text": "\"die Frau Sopherl vom Naschmarkt\" (Determinativkompositum aus [[Naschmarkt]]=\"größter innerstädtischer Markt Wiens\" und [[Sopherl]]=Kosename für \"Sophie\")"}, {"kategorie": "hist.", "text": "Inbegriff einer Wiener Naschmarkt-Standlerin (\"die Frau Sopherl\" ist eine Figur von Vincenz Chiavacci, einem humorvollen Schilderer des Wiener Lebens im ausgehenden 19. und beginnenden 20. Jahrhundert, der seine Protagonistin in einer Zeitungskolumne hunderte humorvolle „lokalpolitische Standreden“ zu verschiedensten Themen halten ließ, die Wien damals bewegten)"}, {"kategorie": "sprichwörtlich", "text": "\"die Stimme aus dem Volk\", \"die Frau von nebenan\", \"die liebe Frau Sopherl vom [[Naschmarkt]]\" (liebevoll-kluge Symbolfigur für die einfache, praktische, oft ältere Frau aus dem Volk – mit Herz, Hausverstand und Humor. Sie steht oft sinnbildlich für Volksmeinung, bodenständige Lebenserfahrung und kritische Alltagsweisheit)"}]'::jsonb, ''),
  ('schdott-aufd-politika-soit-ma-liawa-moi-aufd-frau-soffal-huachn-de-wissad-scho-wos-gerechtigkeit-haasst', 'Schdott aufd Politika soit ma liawa moi aufd Frau Soffal huachn - de wissad scho, wos Gerechtigkeit haasst!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Statt auf die Politiker sollten wir lieber mal auf Frau Sopherl hören – die wüsst schon, was Gerechtigkeit heißt!', '[{"kategorie": "wörtlich", "text": "\"Statt ständig auf Politiker zu hören, sollten wir der Stimme aus dem Volk mehr Raum geben – etwa einer wie Frau Sopherl, die genau weiß, was gerecht ist!\"  2. Statt auf die Politiker sollten wir lieber der Frau Sopherl zuhören – die hat ein besseres G’spür für Gerechtigkeit!  3. Manchmal wär’s gsünder, auf eine Naschmarktstandlerin wie Frau Sopherl zu hören statt auf irgendwelche Politiker!"}]'::jsonb, 'de Frau Soffal'),
  ('mameatus-pankratius-und-servatius-san-drei-frostige-buaschn-vua-bonifaz-ka-summa-noch-da-sofal-ka-frost', 'Mameatus, Pankratius und Servatius san drei frostige Buaschn - vua Bonifaz ka Summa, noch da Sofal ka Frost!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Mamertus, Pankratius und Servatius sind drei frostige Burschen - vor Bonifaz kein Sommer, nach der Sophie kein Frost!', '[{"kategorie": "wörtlich, alte Bauernwetterregel", "text": "\"Mamertus, Pankratius und Servatius sind drei kalte Gesellen - vor Bonifaz kein Sommer, nach der Sophie kein Frost!\"  2. Mamertus, Pankratius und Servatius bringen die letzten frostigen Nächte - vor Bonifaz kein Sommerglück, doch nach der Sophie kommt’s zurück!  3. Mamertus, Pankratius und Servatius bringen Frost und kühlen Schnee - bevor Bonifaz nicht durch ist, ist’s für zarte Pflanzen zu früh, doch nach der kalten Sophie wird’s endlich grün!"}]'::jsonb, ''),
  ('hoid-do-is-a-schboid', 'Hoid, do is a Schboid!', '', '', '', '', 'Halt, da ist ein Spalt!', '[{"kategorie": "wörtlich", "text": "\"Halt, da klafft eine Lücke!\"  2. (scherzhaft für): \"Obacht!\""}]'::jsonb, ''),
  ('fia-mi-is-des-ollas-a-schbanischs-duaf', 'Fia mi is des ollas a schbanischs Duaf!', '', '', '', '', 'Für mich ist das alles ein spanisches Dorf!', '[{"kategorie": "", "text": "Das alles ist für mich wie ein Buch mit sieben Siegeln!  2. Ich verstehe von alldem nur [[Bahnhof]]!  3. [[Das]] alles ist für mich ein [[böhmisches]] Dorf!"}]'::jsonb, ''),
  ('i-vaschdee-nua-baunhof', 'I vaschdee nua Baunhof!', '', '', '', '', 'Ich verstehe nur Bahnhof!', '[{"kategorie": "wörtlich", "text": "\"Ich kann an nichts anderes mehr denken als an Bahnhof\" (die Phrase stammt aus der Zeit des Ersten Weltkrieges (1914-1918): \"Bahnhof\" bedeutete für die Soldaten \"Heimkehr\". Das magische Wort beherrschte sie derart, dass sie an nichts anderes mehr denken und nicht mehr aufmerksam zuhören konnten)"}, {"kategorie": "fig.", "text": "Ich verstehe rein gar nichts!  3. [[Für]] mich ist das ein spanisches Dorf!"}]'::jsonb, ''),
  ('des-ollas-is-fia-mi-a-beemischs-duaf', 'Des ollas is fia mi a beemischs Duaf!', '', '', '', '', 'Das alles ist für mich ein böhmisches Dorf!', '[{"kategorie": "", "text": "Das alles ist für mich wie ein Buch mit sieben Siegeln!  2. Ich verstehe von alldem nur [[Bahnhof]]!  3. Für mich ist das alles ein [[spanisches]] Dorf!"}]'::jsonb, ''),
