  ('i-schbendia-an-doppla-weiss', 'I schbendia an Doppla Weiß!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ich spendiere einen Doppler Weiß!', '[{"kategorie": "wörtlich", "text": "\"Ich spendiere einen Doppelliter Weißwein!\"  2. \"Ich lade euch alle auf einen Doppelliter Weißwein ein!\"  3. \"Der nächste Doppler geht auf mich!\""}]'::jsonb, ''),
  ('des-kaunna-si-ned-hintan-schbiagl-schdeckn', 'Des kaunna si ned hintan Schbiagl schdeckn!', '', '', '', '', 'Das kann er sich nicht hinter den Spiegel stecken!', '[{"kategorie": "", "text": "Das kann er nicht so einfach ausblenden!  2. Das lässt sich nicht so leicht verdrängen!  3. Das kann er nicht so einfach ignorieren!"}]'::jsonb, ''),
