  ('si-mit-wos-schbueuen', 'si mit wos schbüün', '', '', '', '', 'sich mit etwas spielen', '[{"kategorie": "", "text": "etwas problemlos meistern, etwas aus dem Handgelenk erledigen"}, {"kategorie": "", "text": "etwas halbherzig betreiben, mit etwas herumexperimentieren, herumprobieren"}]'::jsonb, ''),
  ('schbueue-ned-auf-augriad', 'Schbüü ned auf augriad!', '', '', '', '', 'Spiele nicht auf angerührt!', '[{"kategorie": "", "text": "Spiele nicht den Eingeschnappten!  2. Tu bloß nicht so, als wärst du zutiefst verletzt!"}]'::jsonb, ''),
  ('schee-warads-schoo-owa-schbueuen-dansas-leida-ned', 'Schee warads schoo, owa schbüün dansas leida ned!', '', '', '', '', 'Schön wäre es schon, aber spielen tun sie es leider nicht!', '[{"kategorie": "", "text": "Schön wäre es schon, aber es soll halt leider nicht sein!  2. Es wäre eine tolle Sache gewesen, aber es sollte halt nicht sein!"}]'::jsonb, ''),
  ('dea-schbueued-olle-foam', 'Dea schbüüd olle Foam!', '', '', '', '', 'Der spielt alle Farben!', '[{"kategorie": "", "text": "Er wechselt die Gesichtsfarbe wie ein Chamäleon!  2. Er wird abwechselnd blass und rot im Gesicht!"}]'::jsonb, ''),
  ('imma-dessoewe-gschbuelettl', 'Imma dessöwe Gschbülettl!', '', '', '', '', 'Immer dasselbe Gspielettl!', '[{"kategorie": "", "text": "Immer dasselbe Spielchen!  2. Es ist immer dieselbe Geschichte!"}]'::jsonb, ''),
  ('si-schbiissn', 'si schbiissn', '', '', '', '', 'sich spießen', '[{"kategorie": "wörtlich", "text": "sich verklemmen, [[sich]] speilen"}, {"kategorie": "", "text": "klemmen, festgeklemmt sein, eingezwickt sein, sich nicht bewegen lassen (von Gegenständen)"}, {"kategorie": "", "text": "stocken, festgefahren sein (Verhandlungen, etc.)"}, {"kategorie": "", "text": "mit etwas nicht vereinbar sein, mit etwas nicht in Einklang zu bringen sein"}, {"kategorie": "von Personen", "text": "sich weigern, sich sträuben, sich gegen etwas stemmen"}]'::jsonb, ''),
