  ('ea-schbiissd-si-gegn-ollas-und-jedn', 'Ea schbiissd si gegn ollas und jedn!', '', '', '', '', 'Er spießt sich gegen alles und jeden!', '[{"kategorie": "", "text": "Er sträubt sich gegen alles und jeden!  2. Er stemmt sich gegen alles und jeden!"}]'::jsonb, ''),
