  ('an-schbinood-mochn', 'an Schbinood mochn', '', '', '', '', 'einen Spinat machen', '[{"kategorie": "", "text": "ein Schlamassel anrichten"}, {"kategorie": "", "text": "Mist bauen, \"sich anpatzen\""}]'::jsonb, ''),
  ('des-is-da-heechste-schbinood', 'Des is da heechste Schbinood!', '', '', '', '', 'Das ist der höchste Spinat!', '[{"kategorie": "", "text": "Das ist das Allergrößte!  2. Das ist das Nonplusultra!  3. Das ist unerreicht!"}]'::jsonb, ''),
  ('de-schbinarin-aum-kreiz', 'De Schbinarin aum Kreiz', '', '', '', '', 'Die Spinnerin am Kreuz', '[{"kategorie": "", "text": "Favoritner Wahrzeichen (prominente gotische Wegemarkierung und Bildsäule aus Sandstein in [[Wien-Favoriten]] [10. Bezirk] an der historisch bedeutenden Triester Straße am westlichen Kamm des [[Wienerbergs]])"}, {"kategorie": "hist.", "text": "Die Spinnerin am Kreuz wurde 1452 errichtet und diente ursprünglich als Pestsäule und Flurkreuz. Der Name des Kreuzes geht auf eine Legende zurück, nach der eine Frau an dieser Stelle saß und für ihren im Krieg befindlichen Mann spinnte, während sie auf seine Rückkehr wartete"}, {"kategorie": "", "text": "Die Spinnerin am Kreuz ist ein gotisches Steinkreuz, das reich mit Figuren und Ornamenten verziert ist. Das Kreuz ist etwa 6 Meter hoch und hat eine Basis mit mehreren Figuren, die biblische Szenen und Heilige darstellen. Im oberen Teil des Kreuzes befindet sich eine Darstellung der Kreuzigung Christi, was ihm auch eine religiöse Bedeutung verleiht."}]'::jsonb, ''),
  ('si-an-schbitzn', 'si an schbitzn', '', '', '', '', 'sich einen spitzen', '[{"kategorie": "wörtlich", "text": "\"sich einen spitz machen\" (vom mittelhochdeutschen \"spitzen\"=\"spitz machen\")"}, {"kategorie": "scherzhaft für", "text": "onanieren, wichsen, [[jankern]], [[schwarteln]]"}, {"kategorie": "", "text": "sich selbst befriedigen, [[sich]] einen schälen, [[sich]] einen runterrebeln, [[den]] Kasperl schnäuzen"}]'::jsonb, ''),
  ('auf-wos-schbitzn', 'auf wos schbitzn', '', '', '', '', 'auf etwas spitzen', '[{"kategorie": "", "text": "ein Auge auf etwas geworfen haben, sich etwas erhoffen"}, {"kategorie": "", "text": "gierig auf etwas sein, wild auf etwas sein"}, {"kategorie": "", "text": "begierig auf etwas sein, versessen auf etwas sein, [[sierig]] auf etwas sein"}]'::jsonb, ''),
  ('fia-an-schbitz-hobi-mi-sunst-imma-so-scheniad', 'Fia an Schbitz hobi mi sunst imma so scheniad!', '', '', '', '', 'Für einen Spitz habe ich mich sonst immer so geniert!', '[{"kategorie": "wörtlich", "text": "Für einen Schuss mit der Schuhspitze habe ich mich sonst immer so geschämt!  2. legendärer Ausspruch des österreichischen Teamspielers Herbert Prohaska, der Österreichs Nationalteam gegen die Türkei 1978 mit seinem [[Spitz]] von Izmir zur Fußballweltmeisterschaft in Argentiniens schoss)"}]'::jsonb, ''),
  ('da-schbitz-von-izmir', 'Da Schbitz von Izmir', '', '', '', '', 'Der Spitz von Izmir', '[{"kategorie": "wörtlich", "text": "\"Der Schuhspitzenkick von Izmir\""}, {"kategorie": "Fußballerjargon", "text": "Der legendäre Schuss des österreichischen Teamspielers Herbert Prohaska, der Österreichs Nationalteam gegen die Türkei 1978 mit einem [[Spitz]] zur Fußballweltmeisterschaft in Argentiniens schoss)"}]'::jsonb, ''),
