  ('si-is-a-schdaadarin-aum-schdrich', 'Si is a Schdaadarin aum Schdrich!', '', '', '', '', 'Sie ist eine Starterin am Strich!', '[{"kategorie": "wörtlich", "text": "\"Sie ist Neuanfängerin am Strich!\"  2. (Gaunersprache): Sie ist als Strichmädchen neu auf dem Markt!  3. Sie ist als [[Hackenbraut]] neu im Gewerbe!"}]'::jsonb, ''),
  ('dea-schdaazd-dahea-wia-da-kaisa-von-china', 'Dea schdaazd dahea wia da Kaisa von China!', '', '', '', '', 'Der stolziert herein wie der Kaiser von China!', '[{"kategorie": "", "text": "Der stelzt herein, als gehörte ihm die Welt!  2. Der schwebt herein wie ein Pfau auf Stelzen!  3. Er stolziert herein wie der große Zampano!"}]'::jsonb, ''),
  ('si-wos-schdassn', 'si wos schdassn', '', '', '', '', 'sich etwas stassen', '[{"kategorie": "wörtlich", "text": "\"sich etwas krallen\""}, {"kategorie": "", "text": "sich etwas unter den Nagel reißen"}, {"kategorie": "", "text": "etwas heimlich mitgehen lassen"}]'::jsonb, 'Des Handy hoda si gschdassd!'),
  ('host-scho-wiida-wos-gschdassd', 'Host scho wiida wos gschdassd?', '', '', '', '', 'Hast du schon wieder etwas gestasst?', '[{"kategorie": "", "text": "Hast du schon wieder etwas gestohlen?  2. Was hast du diesmal wieder geklaut?"}]'::jsonb, ''),
  ('des-handy-hoda-si-gschdassd', 'Des Handy hoda si gschdassd!', '', '', '', '', 'Das Handy hat er sich gestasst!', '[{"kategorie": "", "text": "Das Handy hat er sich unter den Nagel gerissen!  2. Das Handy hat er sich heimlich gekrallt!  3. Das Handy hat er einfach so mitgehen lassen!"}]'::jsonb, 'si wos schdassn'),
  ('der-schdaubd-in-ana-schdund-10-gschbritzde', 'Der schdaubd in ana Schdund 10 Gschbritzde!', '', '', '', '', 'Der staubt in einer Stunde 10 Gespritzte!', '[{"kategorie": "wörtlich", "text": "\"Der kippt in einer Stunde 10 Gespritzte!\"  2. Der trinkt in einer Stunde zehn Viertelgläser Spritzwein!  3. Er haut sich in einer Stunde zehn Gläser Spritzwein rein!"}]'::jsonb, ''),
  ('gemma-an-tschik-schdaum', 'Gemma an Tschik schdaum!', '', '', '', '', 'Gehen wir eine Zigarette stauben!', '[{"kategorie": "", "text": "Gehen wir eine Zigarette paffen!  2. Lass uns eine Zigarette schmauchen gehen!  3. Gehen wir uns einen Tschick anzünden!"}]'::jsonb, ''),
  ('da-puivaschnaeae-schdaubd-unta-de-schi', 'Da Puivaschnää schdaubd unta de Schi!', '', '', '', '', 'Der Pulverschnee staubt unter den Skiern!', '[{"kategorie": "", "text": "Der Pulverschnee wirbelt unter den Skiern hoch!  2. Der Pulverschnee stob unter den Skiern hoch!"}]'::jsonb, ''),
  ('des-schdaubd-ma-scho-bei-de-uawaschln-ausse', 'Des schdaubd ma scho bei de Uawaschln ausse!', '', '', '', '', 'Das staubt mir schon bei den Ohrwascheln raus!', '[{"kategorie": "wörtlich", "text": "Das staubt mir schon bei den Ohren heraus!  2. Mir hängt das alles schon beim Hals raus!  3. (Kulinarik): Das ist derart trocken, dass es mir schon bei den Ohren herausstaubt! (z.B. eingetrocknete Mehlspeise, trockener Unterrichtsstoff, etc.)"}]'::jsonb, ''),
  ('den-hiasl-in-sein-meazl-haumma-gschdaubd', 'Den Hiasl in sein Meazl haumma gschdaubd!', '', '', '', '', 'Diesen Dolm in seinem Mercedes haben wir gestaubt!', '[{"kategorie": "", "text": "Diesen Dodel in seinem Mercedes haben wir abgehängt!  2. Diesen [[Dillo]] in seinem Mercedes haben wir hinter uns gelassen!  3. Diesem Deppen in seinem Mercedes haben wir den Auspuff gezeigt!"}]'::jsonb, ''),
  ('wem-in-schdeckn-geem', 'wem in Schdeckn geem', '', '', '', '', 'jemandem den Stecken geben', '[{"kategorie": "wörtlich", "text": "\"jemandem den Gehstock geben und für immer fortschicken\""}, {"kategorie": "", "text": "jemandem den Laufpass geben, jemanden vor die Tür setzen, jemandem den [[Weisel]] geben"}]'::jsonb, ''),
  ('in-schdeckn-kriang', 'in Schdeckn kriang', '', '', '', '', 'den Stecken kriegen', '[{"kategorie": "wörtlich", "text": "\"den Gehstock kriegen und für immer fortschickt werden\""}, {"kategorie": "", "text": "den Laufpass verpasst bekommen, vor die Tür gesetzt werden, den [[Weisel]] kriegen"}]'::jsonb, ''),
  ('in-schdeckn-haum', 'in Schdeckn haum', '', '', '', '', 'den Stecken haben', '[{"kategorie": "wörtlich", "text": "\"den Gehstock in die Hand gedrückt bekommen und für immer fortschickt werden\""}, {"kategorie": "", "text": "den Laufpass verpasst bekommen, vor die Tür gesetzt werden, den [[Weisel]] kriegen, den [[Hahn]] haben"}]'::jsonb, ''),
  ('in-hund-des-schdeckal-weafn', 'in Hund des Schdeckal weafn', '', '', '', '', 'dem Hund das Steckerl werfen', '[{"kategorie": "wörtlich", "text": "\"dem Hund das Stöckchen werfen\""}, {"kategorie": "", "text": "dem Hund das Apportierstöckchen werfen"}]'::jsonb, ''),
  ('schdeckal-in-oasch', 'Schdeckal in Oasch!', '', '', '', '', 'Steckerl im Arsch!', '[{"kategorie": "wörtlich", "text": "\"Stöckchen im Arsch!\""}, {"kategorie": "Ausruf und herablassende Reaktion auf einen dummen Sager", "text": "Quatsch!  Firlefanz!  Kokolores!  Papperlapapp!"}]'::jsonb, ''),
  ('deen-schdeffae-reim', 'deen Schdeffä reim', '', '', '', '', 'den Steffl reiben', '[{"kategorie": "wörtlich, historisch", "text": "\"öffentliche Kirchenbuße tun\" (\"gefallene Mädchen\" mussten einst, in ärmliche Kleider gehüllt, mit bloßen Füßen und einem Strohkranz in der Hand oder auf dem Kopfe vor den Kirchentüren stehen und durch den Spott der Vorübergehenden ihre Sünden abbüßen. Solche Mädchen fanden auch selten mehr einen Mann, der sie zum Traualtar führte, daher das Volk den Strohkranz in den Händen der Dirne mit einem Abreibwische verglich und meistens höhnisch die Unglückliche aufforderte, doch das Gotteshaus oder dessen Turm damit tüchtig \"zu reiben\" [abzuputzen])"}, {"kategorie": "scherzhaft für", "text": "ewig unverheiratet bleiben, das ewige Single-Dasein fristen, in der ewigen Single-Falle feststecken"}]'::jsonb, ''),
  ('palaeae-palffy', 'Palää Palffy', '', '', '', '', 'Palais Palffy', '[{"kategorie": "hist.", "text": "historisches Stadtpalais im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Es liegt am [[Josefsplatz]] und hat eine lange Geschichte, die eng mit der aristokratischen Familie Pálffy von Erdőd verbunden ist, nach der das Palais benannt ist"}, {"kategorie": "", "text": "Das Palais wurde im 16. Jahrhundert errichtet und im Laufe der Zeit mehrfach umgebaut. Es zeigt architektonische Elemente aus verschiedenen Epochen, darunter Renaissance und Barock. Das heutige Aussehen des Gebäudes stammt größtenteils aus dem 18. Jahrhundert, als es umfassend renoviert und erweitert wurde"}, {"kategorie": "", "text": "Das Palais Palffy ist besonders für seine musikgeschichtliche Bedeutung bekannt. Wolfgang Amadeus Mozart und Ludwig van Beethoven gaben hier Konzerte. Das Palais war ein Treffpunkt für die Wiener Musikwelt und beherbergte zahlreiche bedeutende musikalische Veranstaltungen."}]'::jsonb, ''),
  ('palaeae-harrach', 'Palää Harrach', '', '', '', '', 'Palais Harrach', '[{"kategorie": "hist.", "text": "bedeutendes barockes Stadtpalais im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Es liegt an der [[Freyung]] und gehört zu den beeindruckendsten Beispielen barocker Architektur in Wien"}, {"kategorie": "", "text": "Das Palais Harrach wurde im 17. Jahrhundert erbaut und diente der einflussreichen Adelsfamilie Harrach als Stadtresidenz. Die Familie Harrach war eine bedeutende österreichische Adelsfamilie, die über Jahrhunderte hinweg eine wichtige Rolle in der Politik und im kulturellen Leben der [[Habsburgermonarchie]] spielte. Das Palais wurde zwischen 1690 und 1728 unter der Leitung des Architekten Christian Alexander Oedtl im Stil des Hochbarock erbaut"}, {"kategorie": "", "text": "Die Fassade des Gebäudes ist durch klare Linien und dekorative Elemente geprägt, die typisch für den Barockstil sind. Besonders bemerkenswert ist das Hauptportal, das von mächtigen Säulen flankiert wird und in einen prächtigen Innenhof führt. Der Innenhof ist durch Arkaden und eine elegante Gestaltung gekennzeichnet, die die Pracht und den Reichtum der Familie Harrach widerspiegeln."}]'::jsonb, ''),
  ('kaeantna-schdrossn', 'Käantna Schdrossn', '', '', '', '', 'Kärntnerstraße', '[{"kategorie": "allg.", "text": "eine der bekanntesten und bedeutendsten Einkaufsstraßen in Wien, gelegen im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Sie erstreckt sich vom [[Stephansplatz]] bis zur [[Wiener]] Staatsoper am [[Opernring]]"}, {"kategorie": "", "text": "Die Wiener Kärntner Straße war bereits bei den Römern bekannt. Sie verband damals das Stadtzentrum mit dem [[Kärntner]] Tor und dem Teil der Stadtmauer, die sich in der Nähe der jetzigen Staatsoper vollzog. Damals war sie eine wichtige Handelsverbindung, da ihre Verlängerung zu den Hafenstädten Venedig und Triest führte"}, {"kategorie": "", "text": "Heute ist die Kärntner Straße eine der bekanntesten Einkaufsstraßen Wiens und eine zentrale Fußgängerzone. Sie ist gesäumt von zahlreichen internationalen Marken, exklusiven Boutiquen, Juwelieren, Kaufhäusern und Restaurants. Die Straße ist ein beliebtes Ziel für Touristen und Einheimische gleichermaßen, die hier einkaufen, flanieren und die Architektur bewundern."}]'::jsonb, ''),
  ('piaristnkiachn-maria-treu', 'Piaristnkiachn Maria Treu', '', '', '', '', 'Piaristenkirche Maria Treu', '[{"kategorie": "allg.", "text": "bedeutende barocke Kirche im 8. Wiener Gemeindebezirk ([[Josefstadt]]), die zum Kloster der Piaristen, einem katholischen Orden, gehört"}, {"kategorie": "", "text": "Die Piaristenkirche Maria Treu wurde im 17. Jahrhundert gegründet, nachdem die Piaristen 1697 nach Wien gekommen waren. Der Bau der Kirche begann 1716 und wurde in mehreren Phasen abgeschlossen, wobei die Fassade erst 1753 fertiggestellt wurde. Der Name \"Maria Treu\" bedeutet \"der treuen Maria\" und bezieht sich auf die Marienverehrung, die in der Kirche einen zentralen Platz einnimmt"}, {"kategorie": "", "text": "Die Kirche wurde im Stil des Hochbarock erbaut, der sich durch seine prächtige, dynamische und detailreiche Gestaltung auszeichnet. Der Architekt war vermutlich Lukas von Hildebrandt, einer der führenden Baumeister des Barock in Österreich, der auch an anderen bedeutenden Wiener Bauwerken mitgewirkt hat"}, {"kategorie": "", "text": "Die Fassade der Kirche ist typisch für den Barock und wirkt monumental und gleichzeitig elegant. Sie ist durch [[Pilaster]] und [[Gesimse]] gegliedert und wird von einer Statue der Madonna mit Kind gekrönt. Zwei Türme flankieren die Fassade und geben der Kirche ihre charakteristische Silhouette"}, {"kategorie": "", "text": "Der Innenraum der Kirche ist reich verziert und folgt dem typischen barocken Stil, der durch eine harmonische Mischung von Architektur, Skulptur und Malerei geprägt ist. Besonders beeindruckend sind die Fresken des Malers Franz Anton Maulbertsch, die das [[Gewölbe]] und die Kuppel schmücken. Diese Fresken gelten als Meisterwerke der österreichischen Barockmalerei und stellen Szenen aus dem Leben der Jungfrau Maria und den Piaristen dar"}, {"kategorie": "", "text": "Der Hochaltar der Kirche ist ebenso prächtig gestaltet, mit einer Statue der Maria Immaculata im Zentrum, die von Engeln und Heiligenfiguren umgeben ist. Der Altarbereich ist ein eindrucksvolles Beispiel für die barocke Kunst, die darauf abzielt, den Betrachter emotional zu bewegen und seine Andacht zu vertiefen"}]'::jsonb, ''),
  ('palaeae-auaspeag', 'Palää Auaspeag', '', '', '', '', 'Palais Auersperg', '[{"kategorie": "allg.", "text": "\"prächtiges Barockpalais im 8. Wiener Gemeindebezirk\" ([[Josefstadt]])"}, {"kategorie": "", "text": "Es ist eines der bedeutendsten historischen Gebäude in Wien und hat eine reiche Geschichte als Schauplatz politischer, kultureller und gesellschaftlicher Ereignisse. Heute wird das Palais Auersperg hauptsächlich als Veranstaltungsort für Konzerte, Bälle, Hochzeiten und andere festliche Anlässe genutzt"}, {"kategorie": "", "text": "Das Palais Auersperg wurde zwischen 1706 und 1710 erbaut. Es wurde von dem Architekten Johann Bernhard Fischer von Erlach und seinem Schüler Lukas von Hildebrandt entworfen, zwei der bedeutendsten Barockarchitekten Österreichs. Ursprünglich war das Palais als Stadtresidenz für den Hofmarschall Hieronymus Capece de Rofrano, einen engen Vertrauten des Kaisers, gedacht"}, {"kategorie": "", "text": "Das Palais wechselte im Laufe der Jahrhunderte mehrmals den Besitzer. 1777 ging es in den Besitz der Fürstenfamilie Auersperg über, die dem Palais seinen heutigen Namen gab. Die Familie nutzte das Palais als ihre Wiener Residenz und machte es zu einem Zentrum des gesellschaftlichen Lebens in der Stadt"}, {"kategorie": "", "text": "Die Fassade des Palais Auersperg ist im typischen Stil des Barock gehalten, mit einer symmetrischen Gestaltung und dekorativen Elementen wie Pilastern, Stuckverzierungen und einer imposanten Freitreppe, die zum Hauptportal führt"}, {"kategorie": "", "text": "Die Innenräume des Palais sind ebenso prachtvoll und umfassen große Prunksäle, die reich mit Stuck, Fresken und wertvollen Kunstwerken ausgestattet sind. Der Goldene Saal, der als einer der prächtigsten Räume des Palais gilt, war Schauplatz zahlreicher historischer Ereignisse und Aufführungen"}, {"kategorie": "", "text": "Das Palais Auersperg ist von einem gepflegten Garten umgeben, der ursprünglich im französischen Stil angelegt war. Heute bietet der Garten einen eleganten Rahmen für Outdoor-Veranstaltungen"}, {"kategorie": "", "text": "Das Palais Auersperg war im 18. Jahrhundert ein wichtiger Ort für musikalische Aufführungen. Berühmte Komponisten wie Wolfgang Amadeus Mozart und Christoph Willibald Gluck führten hier ihre Werke auf. Mozart dirigierte im Palais 1786 eine Aufführung seiner Oper \"Idomeneo\""}, {"kategorie": "", "text": "Im 19. Jahrhundert spielte das Palais eine bedeutende Rolle in der politischen Geschichte Wiens. Es war der Schauplatz von diplomatischen Treffen und wichtigen gesellschaftlichen Anlässen während des Wiener Kongresses."}]'::jsonb, ''),
  ('fraunz-josefs-baunhof', 'Fraunz-Josefs-Baunhof', '', '', '', '', 'Franz-Josephs-Bahnhof', '[{"kategorie": "", "text": "Der Bahnhof spielt eine bedeutende Rolle im Schienenverkehr zwischen Wien und dem nördlichen sowie nordwestlichen Niederösterreich, dem Waldviertel und Teilen von Tschechien"}, {"kategorie": "", "text": "Der Franz-Josephs-Bahnhof wurde am 23. Juni 1872 eröffnet und ist nach [[Kaiser]] Franz Joseph I. benannt, dem damaligen österreichischen Monarchen. Er war ursprünglich als Endpunkt der Kaiser Franz Joseph-Bahn konzipiert, einer wichtigen Eisenbahnstrecke, die Wien mit Böhmen und Mähren (heute Teile von Tschechien) verband"}, {"kategorie": "", "text": "Das ursprüngliche Bahnhofsgebäude war ein prächtiger Bau im Stil der [[Gründerzeit]], der die Bedeutung des Bahnhofs als Tor in den Norden des Habsburgerreiches unterstrich. Während des Zweiten Weltkriegs wurde der Bahnhof schwer beschädigt, und das ursprüngliche Gebäude wurde nach Kriegsende nicht in seiner alten Form wiederhergestellt. Stattdessen entstand ein funktionaler Neubau, der den modernen Anforderungen gerecht werden sollte"}, {"kategorie": "", "text": "Der Franz-Josephs-Bahnhof präsentiert sich heute als funktionaler Verkehrsbau, der neben den Bahnanlagen auch Einkaufs- und Dienstleistungseinrichtungen beherbergt. Das Bahnhofsgebäude ist modern und wurde so gestaltet, dass es den Anforderungen eines modernen Stadtbahnhofs entspricht."}]'::jsonb, ''),
  ('wiina-schdoodsopa', 'Wiina Schdoodsopa', '', '', '', '', 'Wiener Staatsoper', '[{"kategorie": "allg.", "text": "\"eines der renommiertesten Opernhäuser der Welt und ein zentraler Bestandteil des kulturellen Lebens in Wien und Österreich\""}, {"kategorie": "", "text": "Sie befindet sich im 1. Wiener Gemeindebezirk, an der Ringstraße ([[Opernring]]) und ist bekannt für ihre lange Tradition, erstklassige Aufführungen und das jährlich stattfindende [[Opernball-Event]]"}, {"kategorie": "", "text": "Die Wiener Staatsoper wurde am 25. Mai 1869 mit einer Aufführung von Mozarts \"Don Giovanni\" eröffnet. Ursprünglich als \"k.k. Hofoperntheater\" bekannt, wurde das Gebäude im Zuge der Errichtung der [[Ringstraße]] erbaut, die anstelle der alten Stadtmauern entstand"}, {"kategorie": "", "text": "Das Gebäude wurde von den Architekten August Sicard von Siccardsburg und Eduard van der Nüll im Stil der Neorenaissance entworfen"}, {"kategorie": "", "text": "Die Wiener Staatsoper ist ein prächtiges Beispiel für die Architektur der Neorenaissance. Die Fassade ist mit zahlreichen Statuen und Reliefs geschmückt, darunter allegorische Darstellungen der Musik, die das Gebäude schmücken"}, {"kategorie": "", "text": "Das Innere der Staatsoper ist ebenso beeindruckend, mit einem prächtigen Zuschauerraum, der Platz für etwa 1.700 Gäste bietet, und einem Orchestergraben, der für rund 100 Musiker ausgelegt ist. Die Innenräume sind luxuriös mit Marmor, Stuck und Fresken verziert"}, {"kategorie": "", "text": "Das Haus verfügt über ein festes Ensemble von Solisten, einem Chor und dem berühmten Orchester, das gleichzeitig als [[Wiener]] Philharmoniker auftritt"}, {"kategorie": "", "text": "Der [[Wiener]] Opernball, der jedes Jahr in der Staatsoper stattfindet, ist eines der gesellschaftlichen Highlights in Österreich und zieht prominente Gäste aus aller Welt an."}]'::jsonb, ''),
  ('schbanische-hofreidschui', 'Schbanische Hofreidschui', '', '', '', '', 'Spanische Hofreitschule', '[{"kategorie": "allg.", "text": "\" traditionsreiche Institution in Wien, die weltweit für ihre klassische Reitkunst und die Ausbildung der Lipizzaner-Pferde bekannt ist\""}, {"kategorie": "", "text": "Sie ist die älteste Reitschule ihrer Art und eine der wenigen Orte, an denen die klassische Reitkunst der Renaissance in ihrer ursprünglichen Form erhalten geblieben ist"}, {"kategorie": "", "text": "Sie ist im Michaelertrakt der [[Hofburg]] untergebracht und diente ursprünglich der reiterlichen Ausbildung der kaiserlichen Familie"}, {"kategorie": "", "text": "Die Spanische Hofreitschule wurde im Jahr 1572 erstmals urkundlich erwähnt und geht auf die Tradition der höfischen Reitkunst am Wiener Hof zurück. Der Name \"Spanische Hofreitschule\" bezieht sich auf die spanischen Pferde, insbesondere die Lipizzaner, die seit dem 16. Jahrhundert am österreichischen Kaiserhof gezüchtet und ausgebildet werden"}, {"kategorie": "", "text": "Die Vorführungen und das Training der Lipizzaner finden hauptsächlich in der barocken Winterreitschule der Hofburg statt, die zwischen 1729 und 1735 unter [[Kaiser]] Karl VI. von Joseph Emanuel Fischer von Erlach erbaut wurde. Der prachtvolle Saal, der für die öffentlichen Vorführungen genutzt wird, ist mit Kronleuchtern, hohen Decken und eleganten Emporen ausgestattet und gilt als einer der schönsten Reitsäle der Welt"}, {"kategorie": "", "text": "Die Spanische Hofreitschule ist berühmt für die klassische Reitkunst, die auf den Prinzipien der Harmonie zwischen Reiter und Pferd basiert. Die Ausbildung der Lipizzaner umfasst Dressurlektionen und anspruchsvolle Kunststücke, wie die \"Schulsprünge\", die nur von wenigen Pferden weltweit beherrscht werden."}]'::jsonb, ''),
  ('wiiner-albertina', 'Wiiner Albertina', '', '', '', '', 'Wiener Albertina', '[{"kategorie": "allg.", "text": "\"eines der bedeutendsten Kunstmuseen in Wien und weltweit bekannt für ihre umfangreiche Sammlung an Grafiken, Zeichnungen und Druckgrafiken\""}, {"kategorie": "", "text": "Sie befindet sich im 1. Wiener Gemeindebezirk, in der Nähe der [[Wiener]] Staatsoper und der [[Hofburg]]. Das Museum ist in einem prachtvollen historischen Gebäude untergebracht, das einst als Residenz für Mitglieder der Habsburger-Dynastie diente"}, {"kategorie": "", "text": "Die Albertina wurde 1776 von Herzog Albert von Sachsen-Teschen, einem Schwiegersohn von Kaiserin Maria Theresia, gegründet. Sie entstand aus der persönlichen Sammlung des Herzogs, die er im Laufe seines Lebens durch den Erwerb bedeutender Kunstwerke stetig erweiterte"}, {"kategorie": "", "text": "Das Museum ist nach Herzog Albert benannt. Die Sammlung wuchs unter seiner Leitung und später unter seinen Nachfolgern, zu einer der größten und bedeutendsten grafischen Sammlungen der Welt heran"}, {"kategorie": "", "text": "Die Albertina befindet sich im [[Palais]] Erzherzog Albrecht, einem barocken Stadtpalais, das im Laufe der Jahrhunderte mehrmals umgebaut wurde und heute eine prächtige Mischung aus barocker und [[klassizistischer]] Architektur darstellt"}, {"kategorie": "", "text": "Die Albertina beherbergt eine der weltweit bedeutendsten Sammlungen von Zeichnungen, Aquarellen und Druckgrafiken. Zu den Highlights der Sammlung gehören Werke von Albrecht Dürer, Michelangelo, Raphael, Rembrandt, Pieter Bruegel dem Älteren, Rubens und vielen anderen Meistern der europäischen Kunstgeschichte"}, {"kategorie": "", "text": "Dürers \"Feldhase\" und \"Betende Hände\" zählen zu den berühmtesten Exponaten der Albertina"}, {"kategorie": "", "text": "Neben der historischen grafischen Sammlung besitzt die Albertina auch bedeutende Bestände moderner und zeitgenössischer Kunst, darunter Werke von Pablo Picasso, Egon Schiele, Gustav Klimt, Wassily Kandinsky und weiteren Künstlern des 19. und 20. Jahrhunderts"}, {"kategorie": "", "text": "Die Albertina verfügt über prunkvolle Innenräume, die teilweise im Stil des Klassizismus und Empire gestaltet sind. Diese Räume geben einen Einblick in die Pracht der ehemaligen Habsburger Residenz und sind selbst ein bedeutendes kulturelles Erbe"}, {"kategorie": "", "text": "Ein markantes architektonisches Merkmal der Albertina ist der sogenannte \"Flügel des Erzherzogs\", eine monumentale Freitreppe mit einer modernen Überdachung, die das historische Gebäude mit zeitgenössischer Architektur verbindet."}]'::jsonb, ''),
  ('kunsthistorisches-museum', 'Kunsthistorisches Museum', '', '', '', '', 'Kunsthistorisches Museum', '[{"kategorie": "allg.", "text": "\"eines der bedeutendsten und größten Kunstmuseen der Welt\", kurz auch [[KHM]] genannt"}, {"kategorie": "", "text": "Es befindet sich im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), an der [[Ringstraße]], gegenüber dem [[Naturhistorischen]] Museum, mit dem es eine symmetrische architektonische Einheit bildet"}, {"kategorie": "", "text": "Das Kunsthistorische Museum wurde von den Architekten Gottfried Semper und Carl von Hasenauer entworfen. Es wurde errichtet, um die kaiserlichen Kunstsammlungen der Öffentlichkeit zugänglich zu machen und ist ein prächtiges Beispiel für den [[Historismus]] des 19. Jahrhunderts"}, {"kategorie": "", "text": "Das Museum wurde 1891 unter Kaiser Franz Joseph I. eröffnet, zusammen mit dem gegenüberliegenden Naturhistorischen Museum. Beide Gebäude sind Teil des großen Ringstraßenprojekts, das nach dem Abriss der Stadtmauern im 19. Jahrhundert realisiert wurde"}, {"kategorie": "", "text": "Das Gebäude ist im Stil der italienischen Renaissance erbaut und zeichnet sich durch seine imposante Kuppel und die reich verzierten Fassaden aus. Die Innenräume sind ebenso prächtig gestaltet, mit Marmortreppen, großen Korridoren, Kuppelräumen und opulenten Deckenfresken, die von Künstlern wie Gustav Klimt, Ernst Klimt und Franz Matsch geschaffen wurden. Die prächtige Eingangshalle und die Haupttreppe sind architektonische Highlights und bieten den Besuchern einen ersten Eindruck von der künstlerischen Pracht des Museums"}, {"kategorie": "", "text": "Die Gemäldegalerie des Kunsthistorischen Museums zählt zu den bedeutendsten der Welt. Sie enthält Meisterwerke von Künstlern wie Pieter Bruegel dem Älteren, Albrecht Dürer, Raffael, Caravaggio, Peter Paul Rubens, Rembrandt und Diego Velázquez. Besonders hervorzuheben ist die Sammlung von Gemälden Pieter Bruegels, die die größte ihrer Art weltweit ist"}, {"kategorie": "", "text": "Die Kunstkammer Wien ist eine der bedeutendsten Sammlungen ihrer Art und umfasst kunsthandwerkliche Meisterwerke, Kuriositäten und wissenschaftliche Instrumente aus der Renaissance und dem Barock. Sie enthält berühmte Stücke wie die Saliera von Benvenuto Cellini"}, {"kategorie": "", "text": "Das Münzkabinett des Museums ist eine der größten und ältesten Sammlungen von Münzen, Medaillen und Geldscheinen der Welt"}, {"kategorie": "", "text": "Weitere bedeutende Sammlungen sind die Ägyptisch-Orientalische Sammlung (umfasst eine der bedeutendsten Sammlungen altägyptischer Kunst und Kultur in Europa, darunter die berühmte Totenmaske der Königin Teje und zahlreiche Sarkophage, Statuen und Reliefs) sowie die Antikensammlung (umfasst griechische, römische und etruskische Kunstwerke, darunter Skulpturen, Vasen und Mosaiken)"}]'::jsonb, ''),
  ('natuahistorisches-museum', 'Natuahistorisches Museum', '', '', '', '', 'Naturhistorisches Museum', '[{"kategorie": "allg.", "text": "\"eines der größten und bedeutendsten naturkundlichen Museen der Welt\""}, {"kategorie": "", "text": "Es befindet sich im 1. Wiener Gemeindebezirk (Innere Stadt\" am [[Maria-Theresien-Platz]], gegenüber dem [[Kunsthistorischen]] Museum, mit dem es eine architektonische Zwillingsstruktur bildet"}, {"kategorie": "", "text": "Das Museum ist für seine umfangreiche Sammlung an Exponaten aus den Bereichen Mineralogie, Paläontologie, Anthropologie und Zoologie bekannt"}, {"kategorie": "", "text": "Das Naturhistorische Museum wurde zwischen 1871 und 1889 erbaut, nach Plänen der Architekten Gottfried Semper und Carl von Hasenauer. Es wurde errichtet, um die kaiserlichen Naturaliensammlungen der Öffentlichkeit zugänglich zu machen"}, {"kategorie": "", "text": "Das Museum wurde 1889 offiziell eröffnet und beherbergte von Anfang an die umfassenden Sammlungen der Habsburger, die bereits im 18. Jahrhundert begonnen wurden"}, {"kategorie": "", "text": "Das Naturhistorische Museum ist im Stil des [[Historismus]] erbaut, mit einer prächtigen Fassade, die von zahlreichen Figuren und Reliefs geschmückt ist, die Naturwissenschaften und Wissenschaftler darstellen. Das Innere des Gebäudes ist ebenso beeindruckend, mit einer großen Kuppelhalle, prunkvollen Stiegenhäusern und reich verzierten Sälen"}, {"kategorie": "", "text": "Die zentrale Kuppel des Museums ist ein architektonisches Highlight und dominiert die Silhouette des Gebäudes. Die Kuppel ist mit Darstellungen von Wissenschaftlern und Allegorien der Naturwissenschaften geschmückt."}]'::jsonb, ''),
  ('leopoid-museum', 'Leopoid-Museum', '', '', '', '', 'Leopold-Museum', '[{"kategorie": "allg.", "text": "\"renommiertes Kunstmuseum im [[MuseumsQuartier]] (MQ) im 7. Wiener Gemeindebezirk\" ([[Neubau]])"}, {"kategorie": "", "text": "Es beherbergt eine der weltweit bedeutendsten Sammlungen österreichischer Kunst des 19. und 20. Jahrhunderts, mit einem besonderen Schwerpunkt auf Werken der Wiener Moderne und des österreichischen Expressionismus. Das Museum ist vor allem für seine umfassende Sammlung von Werken von Egon Schiele und Gustav Klimt bekannt"}, {"kategorie": "", "text": "Das Leopold Museum wurde im Jahr 2001 eröffnet und geht auf die Sammlung des österreichischen Kunstsammlers Dr. Rudolf Leopold (1925–2010) und seiner Frau Elisabeth Leopold zurück. Die Sammlung wurde über mehrere Jahrzehnte hinweg zusammengetragen und gilt als eine der bedeutendsten Privatsammlungen österreichischer Kunst."}]'::jsonb, ''),
  ('wiina-secession', 'Wiina Secession', '', '', '', '', 'Wiener Secession', '[{"kategorie": "allg.", "text": "\"ein bedeutendes Ausstellungshaus und ein Symbol für die Wiener Moderne\""}, {"kategorie": "", "text": "Es befindet sich im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), nahe dem [[Naschmarkt]]"}, {"kategorie": "", "text": "Die Wiener Secession wurde 1897 von einer Gruppe von Künstlern gegründet, darunter Gustav Klimt, Koloman Moser, Josef Hoffmann und andere. Diese Künstler wollten sich von den konservativen Kunsttraditionen der damaligen Zeit lösen und gründeten die \"Vereinigung bildender Künstler Österreichs – Secession\". Das Ziel war, moderne Kunstformen zu fördern und ein Forum für die internationale Avantgarde zu schaffen"}, {"kategorie": "", "text": "Gustav Klimt war der erste Präsident der Wiener Secession und spielte eine zentrale Rolle in der Entwicklung der Bewegung. Die Secession wurde zum Zentrum des Wiener Jugendstils, auch bekannt als Art Nouveau, und war maßgeblich an der Entwicklung der Wiener Moderne beteiligt"}, {"kategorie": "", "text": "Das Secessionsgebäude, oft einfach \"Die Secession\" genannt, wurde von dem Architekten Joseph Maria Olbrich entworfen und 1898 eröffnet. Das Gebäude ist ein herausragendes Beispiel für den Jugendstil und gilt als eines der bedeutendsten Bauwerke dieser Epoche"}, {"kategorie": "", "text": "Das auffälligste Merkmal des Gebäudes ist die goldene Kuppel, die aus Hunderten von vergoldeten Lorbeerblättern besteht. Sie wird oft als \"goldenes [[Krauthappel]]\" (goldener Kohlkopf) bezeichnet und ist zu einem ikonischen Symbol der Wiener Secession und der Stadt Wien selbst geworden"}, {"kategorie": "", "text": "Die Fassade des Gebäudes ist mit dem berühmten Motto der Secession geschmückt: „Der Zeit ihre Kunst, der Kunst ihre Freiheit.“ Dieses Zitat spiegelt den revolutionären Geist der Künstlerbewegung wider"}, {"kategorie": "", "text": "Eines der bekanntesten Kunstwerke, das sich im Inneren der Secession befindet, ist der Beethovenfries von Gustav Klimt. Dieses monumentale Wandgemälde wurde 1902 für eine Ausstellung zu Ehren Ludwig van Beethovens geschaffen und gilt als eines der Meisterwerke des Jugendstils."}]'::jsonb, ''),
  ('wiina-ringschdrossn', 'Wiina Ringschdrossn', '', '', '', '', 'Wiener Ringstraße', '[{"kategorie": "historisch", "text": "\"berühmte Prachtstraße in Wien, die das historische Zentrum der Stadt, die Innere Stadt, umschließt.\""}, {"kategorie": "", "text": "Die Wiener Ringstraße entstand in der zweiten Hälfte des 19. Jahrhunderts, nachdem Kaiser Franz Joseph I. im Jahr 1857 den Abriss der alten Stadtbefestigungen angeordnet hatte. An deren Stelle wurde die Ringstraße als großzügiger Boulevard angelegt, der zwischen 1857 und 1865 geplant und in den folgenden Jahrzehnten fertiggestellt wurde.  3. Viele der Gebäude entlang der Ringstraße wurden von namhaften Architekten im Stil der Neorenaissance, Neugotik und des Neobarocks entworfen, und sie spiegeln die kulturelle Blütezeit der [[Habsburgermonarchie]] wider"}, {"kategorie": "", "text": "Die Wiener Ringstraße setzt sich aus folgenden Teilabschnitten zusammen (im Uhrzeigersinn aufgeführt, beginnend im Nordwesten): [[Schottenring]], [[Universitätsring]], [[Dr]].-Karl-Renner-Ring, [[Burgring]], [[Opernring]], [[Kärntner]] Ring, [[Schubertring]], [[Parkring]] und [[Stubenring]]"}]'::jsonb, ''),
  ('wiina-voiksopa', 'Wiina Voiksopa', '', '', '', '', 'Wiener Volksoper', '[{"kategorie": "allg.", "text": "\"eines der bekanntesten Opernhäuser in Wien und ein zentraler Ort für Musiktheater in Österreich\""}, {"kategorie": "", "text": "Sie befindet sich im 9. Wiener Gemeindebezirk ([[Alsergrund]]) und ist auf Operetten, Musicals, klassische Opern und Ballettaufführungen spezialisiert. Die Volksoper ergänzt damit die [[Wiener]] Staatsoper und hat sich einen eigenen Platz im kulturellen Leben Wiens erobert"}, {"kategorie": "", "text": "Die Volksoper wurde 1898 als \"Kaiser-Jubiläums-Stadttheater\" eröffnet, um das 50-jährige Regierungsjubiläum von [[Kaiser]] Franz Joseph I. zu feiern. Ursprünglich als Sprechtheater konzipiert, wurden dort in den ersten Jahren vor allem Schauspiele aufgeführt"}, {"kategorie": "", "text": "1903 begann das Theater, Opern und Operetten in sein Programm aufzunehmen, was zu einem bedeutenden Wandel führte. Ab 1908 spezialisierte sich das Haus vollständig auf das Musiktheater und erhielt 1909 den Namen \"Volksoper\""}, {"kategorie": "", "text": "Das Gebäude der Volksoper ist im Stil der Neorenaissance erbaut und wurde in den Jahren seines Bestehens mehrfach umgebaut und renoviert, um den sich ändernden Anforderungen des Theaterbetriebs gerecht zu werden"}, {"kategorie": "", "text": "Der Zuschauerraum bietet Platz für rund 1.300 Besucher und ist für seine gute Akustik und das intime Ambiente bekannt, das sich für die Aufführung von Operetten und Musicals besonders eignet."}]'::jsonb, ''),
  ('uni-wiin', 'Uni Wiin', '', '', '', '', 'Uni Wien', '[{"kategorie": "kurz für", "text": "\"Universität Wien\" = \"älteste und eine der größten Universitäten im deutschsprachigen Raum\" (auch bekannt als \"Alma Mater Rudolphina\")"}, {"kategorie": "", "text": "Sie liegt an der [[Wiener]] Ringstraße im 1. wiener Gemeindebezirk ([[Innere]] Stadt) und wurde am 12. März 1365 von Herzog Rudolf IV., dem Stifter, sowie dessen Brüdern Albrecht III. und Leopold III. gegründet. Damit ist sie die älteste Universität im heutigen deutschsprachigen Raum und die zweitälteste Universität im damaligen [[Heiligen]] Römischen Reich (nach der Universität Prag)"}, {"kategorie": "", "text": "In den ersten Jahrhunderten ihres Bestehens erlangte die Universität Wien als Zentrum der Scholastik und Theologie internationale Bedeutung. Im 15. Jahrhundert wurde sie zu einer der größten Universitäten Europas"}, {"kategorie": "", "text": "In den folgenden Jahrhunderten blieb die Universität ein wichtiges Zentrum für Wissenschaft und Bildung, auch während der Epoche der Aufklärung, als der Einfluss von Philosophie und Naturwissenschaften wuchs"}, {"kategorie": "", "text": "Die Universität erlebte im 19. Jahrhundert eine Phase des Wachstums und der Reformen, insbesondere unter dem Einfluss der [[Habsburgermonarchie]]"}, {"kategorie": "", "text": "Das markante Hauptgebäude der Universität Wien befindet sich an der [[Ringstraße]], einer der bedeutendsten Straßen Wiens, und wurde zwischen 1877 und 1884 im Stil der Neorenaissance von Heinrich von Ferstel errichtet"}, {"kategorie": "", "text": "Der große Arkadenhof des Hauptgebäudes ist mit Denkmälern berühmter Wissenschaftler geschmückt, die an der Universität Wien wirkten, darunter Persönlichkeiten wie Sigmund Freud (Begründer der Psychoanalyse), Lise Meitner (bedeutende Kernphysikerin), Konrad Lorenz (Begründer der modernen Ethologie bzw. Verhaltensforschung) sowie Erwin Schrödinger (Nobelpreisträger und Pionier der Quantenmechanik)"}, {"kategorie": "", "text": "Einer der berühmtesten Studenten der Universität Wien war der bedeutende Physiker und Begründer der modernen Physik, Albert Einstein. Er studierte dort zwischen 1901 und 1905 und entwickelte während dieser Zeit seine bahnbrechenden Theorien zur speziellen und allgemeinen Relativitätstheorie."}]'::jsonb, ''),
  ('universitaet-wiin', 'Universität Wiin', '', '', '', '', 'Universität Wien', '[{"kategorie": "allg.", "text": "\"älteste und eine der größten Universitäten im deutschsprachigen Raum\" (auch bekannt als [[Alma Mater Rudolphina]])"}, {"kategorie": "", "text": "Sie liegt an der [[Wiener]] Ringstraße im 1. wiener Gemeindebezirk ([[Innere]] Stadt) und wurde am 12. März 1365 von Herzog Rudolf IV., dem Stifter, sowie dessen Brüdern Albrecht III. und Leopold III. gegründet. Damit ist sie die älteste Universität im heutigen deutschsprachigen Raum und die zweitälteste Universität im damaligen [[Heiligen]] Römischen Reich (nach der Universität Prag)"}, {"kategorie": "", "text": "In den ersten Jahrhunderten ihres Bestehens erlangte die Universität Wien als Zentrum der Scholastik und Theologie internationale Bedeutung. Im 15. Jahrhundert wurde sie zu einer der größten Universitäten Europas"}, {"kategorie": "", "text": "In den folgenden Jahrhunderten blieb die Universität ein wichtiges Zentrum für Wissenschaft und Bildung, auch während der Epoche der Aufklärung, als der Einfluss von Philosophie und Naturwissenschaften wuchs"}, {"kategorie": "", "text": "Die Universität erlebte im 19. Jahrhundert eine Phase des Wachstums und der Reformen, insbesondere unter dem Einfluss der [[Habsburgermonarchie]]"}, {"kategorie": "", "text": "Das markante Hauptgebäude der Universität Wien befindet sich an der [[Ringstraße]], einer der bedeutendsten Straßen Wiens, und wurde zwischen 1877 und 1884 im Stil der Neorenaissance von Heinrich von Ferstel errichtet"}, {"kategorie": "", "text": "Der große Arkadenhof des Hauptgebäudes ist mit Denkmälern berühmter Wissenschaftler geschmückt, die an der Universität Wien wirkten, darunter Persönlichkeiten wie Sigmund Freud (Begründer der Psychoanalyse), Lise Meitner (bedeutende Kernphysikerin), Konrad Lorenz (Begründer der modernen Ethologie bzw. Verhaltensforschung) sowie Erwin Schrödinger (Nobelpreisträger und Pionier der Quantenmechanik)"}, {"kategorie": "", "text": "Einer der berühmtesten Studenten der Universität Wien war der bedeutende Physiker und Begründer der modernen Physik, Albert Einstein. Er studierte dort zwischen 1901 und 1905 und entwickelte während dieser Zeit seine bahnbrechenden Theorien zur speziellen und allgemeinen Relativitätstheorie."}]'::jsonb, ''),
  ('alma-mater-rudolphina', 'Alma Mater Rudolphina', '', '', '', '', 'Alma Mater Rudolphina', '[{"kategorie": "allg.", "text": "\"traditioneller lateinischer Name der [[Universität]] Wien, der sich aus den Begriffen \"Alma Mater\" und \"Rudolphina\" zusammensetzt\""}, {"kategorie": "", "text": "\"Alma Mater\" bedeutet - wörtlich übersetzt - „nährende Mutter“. Er wurde im Mittelalter als poetische Bezeichnung für Universitäten verwendet, da sie als „nährende Mutter“ der Bildung und des Wissens betrachtet wurden"}, {"kategorie": "", "text": "Der Zusatz „Rudolphina“ bezieht sich auf Herzog Rudolf IV. von Habsburg, der die Universität Wien im Jahr 1365 gründete. Zu Ehren ihres Gründers wird die Universität daher als \"Rudolphina\" bezeichnet"}]'::jsonb, 'Universität Wiin'),
  ('technische-universitaet', 'Technische Universität', '', '', '', '', 'Technische Universität Wien', '[{"kategorie": "hist.", "text": "\"eine der führenden technischen Universitäten in Österreich und eine bedeutende akademische Institution in Europa\" (abgekürzt [[TU Wien]])"}, {"kategorie": "", "text": "Sie befindet sich im 4. Wiener Gemeindebezirk ([[Wieden]]), in unmittelbarer Nähe zum [[Karlsplatz]], und wurde 1815 als \"k.k. Polytechnisches Institut\" gegründet. Sie ist damit eine der ältesten technischen Hochschulen im deutschsprachigen Raum"}, {"kategorie": "", "text": "Die TU Wien gilt als eine der besten technischen Universitäten in Europa und genießt weltweit hohes Ansehen für ihre Lehre und Forschung. Sie zieht Studierende und Wissenschaftler aus aller Welt an und trägt wesentlich zur akademischen und wissenschaftlichen Landschaft Wiens bei."}]'::jsonb, ''),
  ('museum-fia-aungewaundte-kunst', 'Museum fia Aungewaundte Kunst', '', '', '', '', 'Museum für Angewandte Kunst', '[{"kategorie": "hist.", "text": "\"eines der weltweit führenden Museen für angewandte Kunst und Design\" (abgekürzt [[MAK]])"}, {"kategorie": "", "text": "Es befindet sich im 1. Wiener Gemeindebezirk ([[Innere]] Stadt) am [[Stubenring]] und ist ein zentraler Ort für die Präsentation und Erforschung von Kunsthandwerk, Design, Architektur und Gegenwartskunst"}, {"kategorie": "", "text": "Das MAK wurde 1863 als Österreichisches Museum für Kunst und Industrie gegründet. Es entstand aus der Idee, handwerkliche und industrielle Qualität zu fördern und Inspiration durch das Sammeln und Ausstellen von Kunstwerken zu bieten. Der Gründer, Rudolf von Eitelberger, war ein Pionier in der Kunst- und Designförderung und setzte mit der Gründung des Museums neue Maßstäbe in der Vermittlung von Kunsthandwerk"}, {"kategorie": "", "text": "Eine der bedeutendsten Sammlungen des MAK umfasst Werke der Wiener Werkstätte, einer Designbewegung des frühen 20. Jahrhunderts, die von Künstlern wie Josef Hoffmann und Koloman Moser geprägt wurde. Diese Sammlung ist besonders für ihre hochwertigen Kunstwerke und ihre Bedeutung in der Geschichte des Designs bekannt"}, {"kategorie": "", "text": "Das MAK-Gebäude am Stubenring ist ein architektonisches Meisterwerk des [[Historismus]]. Es wurde von Heinrich von Ferstel entworfen und vereint Elemente der Neorenaissance mit funktionalen Aspekten, die für ein Museum notwendig sind. Die großzügigen Ausstellungsräume und die beeindruckende Fassade machen das MAK zu einem wichtigen kulturellen Wahrzeichen Wiens."}]'::jsonb, ''),
  ('jiidisches-museum', 'Jiidisches Museum', '', '', '', '', 'Jüdisches Museum', '[{"kategorie": "allg.", "text": "\"bedeutendes Kulturinstitut in Wien, das sich der jüdischen Geschichte, Kultur und Religion widmet\""}, {"kategorie": "", "text": "Es gibt zwei Standorte: einen in der [[Dorotheergasse]] und einen am [[Judenplatz]]"}, {"kategorie": "", "text": "Das Museum dokumentiert die über 800-jährige jüdische Geschichte Wiens und Österreichs, die sowohl von einer blühenden Kultur als auch von Verfolgung und Tragödien geprägt ist"}, {"kategorie": "", "text": "Das Jüdische Museum Wien geht auf das weltweit erste jüdische Museum zurück, das im Jahr 1895 in Wien gegründet wurde. Dieses erste Museum wurde von der Israelitischen Kultusgemeinde Wien (IKG) initiiert und diente zur Dokumentation und Bewahrung der jüdischen Geschichte und Kultur"}, {"kategorie": "", "text": "Es wurde jedoch 1938 nach dem Anschluss Österreichs an das [[Deutsche]] Reich von den Nationalsozialisten geschlossen, und seine Sammlungen wurden beschlagnahmt oder zerstört"}, {"kategorie": "", "text": "Erst nach dem Zweiten Weltkrieg und der Gründung der [[Zweiten]] Republik wurde der Wunsch wieder stärker, die jüdische Kultur in Wien zu würdigen und aufzuarbeiten. Das moderne Jüdische Museum Wien wurde schließlich 1988 an seinen heutigen beiden Standorten in der Dorotheergasse (Hauptgebäude) und am Judenplatz (Fundamente der mittelalterlichen Synagoge) wiedereröffnet"}, {"kategorie": "", "text": "Das Jüdische Museum Wien verfügt über eine bedeutende Sammlung von Judaica, Kunstwerken und Dokumenten, die verschiedene Aspekte des jüdischen Lebens in Wien und der Weltgeschichte darstellen. Zu den Höhepunkten der Sammlung gehören: (i) religiöse Objekte (wie Torah-Schreine, Gebetsbücher und Kultgegenstände), (ii) historische Dokumente und Briefe (die das Leben der Wiener Juden und ihre Beiträge zur Stadtgeschichte dokumentieren), (iii) Fotografien und Familienarchive (die einen Einblick in das alltägliche Leben jüdischer Familien in Wien bieten), sowie (iv) Kunstwerke von jüdischen Künstlern, die das jüdische Leben in Österreich und weltweit thematisieren."}]'::jsonb, ''),
  ('mozarthaus-wiin', 'Mozarthaus Wiin', '', '', '', '', 'Mozarthaus Wien', '[{"kategorie": "hist.", "text": "\"Museum und Gedenkstätte, die dem Leben und Werk des Komponisten Wolfgang Amadeus Mozart gewidmet ist\""}, {"kategorie": "", "text": "Es befindet sich im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), in der Domgasse 5, nahe dem [[Stephansdom]].  3. Das Gebäude, in dem das Museum untergebracht ist, ist das einzige noch erhaltene Wiener Wohnhaus Mozarts, in dem er von 1784 bis 1787 lebte und einige seiner bedeutendsten Werke, darunter die Oper \"Die Hochzeit des Figaro\" komponierte"}, {"kategorie": "", "text": "Das Mozarthaus Wien wurde 2006, zum 250. Geburtstag Mozarts, als Museum eröffnet. Der Mittelpunkt des Museums ist die originale Wohnung, in der Mozart mit seiner Familie lebte. Besucher können die Räume besichtigen, in denen er komponierte, unterrichtete und mit seinen Freunden musizierte. Die Ausstellung zeigt originale Möbel, Dokumente, Briefe und Kunstwerke, die einen direkten Bezug zu Mozarts Leben haben."}]'::jsonb, ''),
  ('konservatorium-wiin', 'Konservatorium Wiin', '', '', '', '', 'Konservatorium Wien', '[{"kategorie": "hist.", "text": "\"renommierte Bildungseinrichtung für Musik, Theater und Tanz\" (heute bekannt als \"Musik und Kunst Privatuniversität der Stadt Wien\", kurz \"MUK\")"}, {"kategorie": "", "text": "Es befindet sich an mehreren Standorten in Wien (Hauptstandort: Johannesgasse 4a, 1010 Wien, [[Innere]] Stadt)  und hat eine lange Tradition in der Ausbildung von Künstlern auf höchstem Niveau"}, {"kategorie": "", "text": "Im Jahr 2005 erhielt das Konservatorium den Status einer Privatuniversität und wurde in Konservatorium Wien Privatuniversität umbenannt. Im Jahr 2015 erfolgte eine weitere Umbenennung in Musik und Kunst Privatuniversität der Stadt Wien (MUK), um die Erweiterung des Angebots und die umfassendere künstlerische Ausbildung zu reflektieren."}]'::jsonb, ''),
  ('universitaet-fia-musik-und-doaschdoellende-kunst-wiin', 'Universität fia Musik und doaschdöllende Kunst Wiin', '', '', '', '', 'Universität für Musik und Darstellende Kunst Wien', '[{"kategorie": "", "text": "\"eine der ältesten und renommiertesten Musikhochschulen der Welt\" (abgekürzt: [[mdw]])"}, {"kategorie": "", "text": "Sie befindet sich im 3. Wiener Gemeindebezirk ([[Landstraße]]) und ist eine führende Institution für die Ausbildung in den Bereichen Musik, darstellende Kunst und Film"}, {"kategorie": "", "text": "Die Institution wurde 1817 als \"K.k. Konservatorium der Gesellschaft der Musikfreunde\" gegründet. Sie entwickelte sich rasch zu einem zentralen Ort für die Musikausbildung in Wien - der Stadt, die als eines der bedeutendsten Zentren der klassischen Musik gilt"}, {"kategorie": "", "text": "Im Laufe der Zeit wurde die Institution mehrfach umbenannt. Sie erhielt den Namen Hochschule für Musik und darstellende Kunst Wien in den 1970er Jahren. Seit 1998 trägt sie den Titel Universität für Musik und darstellende Kunst Wien (mdw)"}]'::jsonb, ''),
  ('dea-is-wiara-schdeeaufmandl', 'Dea is wiara Schdeeaufmandl!', '', '', '', '', 'Der ist wie ein Stehaufmännchen!', '[{"kategorie": "", "text": "Der lässt sich durch nichts unterkriegen!  2. Der rappelt sich immer wieder von Neuem auf, als wäre nichts gewesen!"}]'::jsonb, ''),
