  ('de-kauma-gschdoin-bleim', 'De kauma gschdoin bleim!', '', '', '', '', 'Die kann mir gestohlen bleiben', '[{"kategorie": "", "text": "Auf sie kann ich liebend gerne verzichten!  2. Ihr weine ich keine Träne nach!"}]'::jsonb, ''),
  ('glaubsd-i-gee-schdoeoen', 'Glaubsd I gee schdöön?', '', '', '', '', 'Glaubst du, ich gehe stehlen?', '[{"kategorie": "", "text": "Woher, mein Lieber, soll ich das Geld nehmen?  2. Wie, mein Lieber, soll ich mir das leisten können?"}]'::jsonb, ''),
