  ('schdaa-von-innan-seeng', 'Schdaa von innan seeng', '', '', '', 'Wiener Gaunersprache', 'Stein von innen sehen', '[{"kategorie": "wörtlich", "text": "\"die Justizvollzugsanstalt Stein an der Donau (größtes Gefängnis Österreichs) von innen sehen\""}, {"kategorie": "Gaunersprache, scherzhaft für", "text": "im Gefängnis sitzen, auf [[Wachauurlaub]] sein, [[sacklpickn]]"}]'::jsonb, ''),
  ('seit-eam-de-kiiwara-hapsgnumma-haum-siichta-schdaa-von-innan', 'Seit eam de Kiiwara hapsgnumma haum, siichta Schdaa von innan!', '', '', '', 'Wiener Gaunersprache', 'Seit ihn die Kieberer hapsgenommen haben, sieht er Stein von innen!', '[{"kategorie": "wörtlich", "text": "\"Seit ihn die Bullen umgehackt haben, sieht er die Justizvollzugsanstalt Stein von innen!\"  2. Seit ihn die Kriminalpolizei festgenommen hat, ist er auf Wachauurlaub!  3. Seit ihn die Polizei verhaftet hat, sitzt er in Stein an der Donau im Gefängnis!"}]'::jsonb, ''),
  ('auf-wachauualaub-sei', 'auf Wachauualaub sei', '', '', '', 'Wiener Gaunersprache', 'auf Wachauurlaub sein', '[{"kategorie": "wörtlich", "text": "\"Ferien in der Wachau machen\""}, {"kategorie": "Gaunersprache, scherzhaft für", "text": "im Gefängnis sitzen, eine Haftstrafe verbüßen, hinter Gittern sein (in Anspielung darauf, dass sich eines von Österreichs größten Gefängnissen in [[Stein]] an der Donau und somit am Eingang zur [[Wachau]] befindet)"}]'::jsonb, ''),
  ('seit-eam-de-kiiwara-haps-gnumma-haum-isa-auf-wachauualaub', 'Seit eam de Kiiwara haps gnumma haum, isa auf Wachauualaub!', '', '', '', 'Wiener Gaunersprache', 'Seit ihn die Kieberer haps genommen haben, ist er auf Wachauurlaub!', '[{"kategorie": "wörtlich", "text": "\"Seit ihn die Bullen umgehackt haben, sitzt er in der Justizvollzugsanstalt Stein!\"  2. Seit ihn die Kriminalpolizei festgenommen hat, sieht er Stein von innen!  3. Seit ihn die Polizei verhaftet hat, sitzt er in Stein an der Donau im Gefängnis!"}]'::jsonb, ''),
  ('wea-nix-riskiad-kummd-nii-noch-schdaa', 'Wea nix riskiad kummd nii noch Schdaa!', '', '', '', 'Wiener Gaunersprache', 'Wer nichts riskiert, kommt nie nach Stein!', '[{"kategorie": "wörtlich", "text": "\"Wer nichts riskiert, kommt nie in die Justizvollzugsanstalt Stein an der Donau (größtes Gefängnis Österreichs)\""}, {"kategorie": "scherzhaft für", "text": "Wer nicht wagt, der nicht gewinnt!  3. (Kartenspielerjargon): Ohne Risiko kein Gewinn!"}]'::jsonb, ''),
  ('do-sitzn-hundad-joa-schdaa', 'Do sitzn hundad Joa Schdaa!', '', '', '', 'Wiener Gaunersprache', 'Da sitzen hundert Jahre Stein!', '[{"kategorie": "wörtlich", "text": "\"Da sitzen hundert Jahre Gefängnis!\"  2. Die alle zusammen haben mindestens 100 Jahre Gefängnis auf dem Buckel!  3. Bei denen kommen locker 100 Jahre [[Häfen]] zusammen\"  (Zur Erklärung: [[Stein]] steht für \"Justizvollzugsanstalt Stein an der Donau\" [eines der größten Gefängnisse Österreichs])"}]'::jsonb, ''),
  ('allaa-is-a-goidana-schdaa', 'Allaa is a goidana Schdaa!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Allein ist ein goldener Stein!', '[{"kategorie": "wörtlich", "text": "\"Sei allein wie ein Edelstein!\"  2. (fig.) Alleinsein ist Goldes wert!\"  3. Nur allein ist man wirklich frei!"}]'::jsonb, ''),
  ('jeda-daedad-gean-schdaareich-sei-und-staaoid-wean', 'Jeda dädad gean schdaareich sei und staaoid wean!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Jeder täte gern steinreich sein und steinalt werden!', '[{"kategorie": "wörtlich", "text": "\"Jeder träumt davon, reich zu sein und alt zu werden!\"  2. Steinreich sein und steinalt werden - das wäre unser aller Traum!\"  3. Satt an Geld und reich an Jahren – so malt sich jeder sein Glück!"}]'::jsonb, ''),
  ('wea-na-da-schdaascheissa-koarl', 'Wea? Na da Schdaascheissa Koarl!', '', '', '', '', 'Wer? Na der Steinscheißer-Karl!', '[{"kategorie": "", "text": "Na wer wohl?  Das weißt du doch selbst am besten!  2. Na wer wohl? Das liegt doch klar auf der Hand!  (Zur Erklärung: \"Steinscheißer-Karl\" ist der Name eines \"Tabuwort-Spiels\", das der Kabarettist Josef Hader zu einer im Wiener Raum nunmehr alltäglichen Redewendung gemacht hat. Sie wird immer dann verwendet, wenn jemand nach einem \"Wer\" fragt, obwohl der Fragende selbst ganz genau weiß, wer gemeint ist)"}]'::jsonb, ''),
  ('schdeirisch-kongo', 'Schdeirisch-Kongo', '', '', '', '', 'Steirisch-Kongo', '[{"kategorie": "", "text": "Gradišće (kroatischer Name für das östlichste Bundesland Österreichs, das von manchen Steirern immer noch als rückständig betrachtet wird)"}]'::jsonb, ''),
