  ('sis-mit-wem-guad-schdoeoen', 'sis mit wem guad schdöön', '', '', '', '', 'es sich mit jemandem gut stellen', '[{"kategorie": "", "text": "ein gutes Verhältnis mit jemandem herstellen"}, {"kategorie": "", "text": "eine positive Beziehung zu jemandem aufbauen"}, {"kategorie": "", "text": "sich mit jemandem arrangieren, aussöhnen"}]'::jsonb, ''),
