  ('schdeandal-schaun', 'Schdeandal schaun', '', '', '', '', 'Sternchen schauen', '[{"kategorie": "wörtlich", "text": "\"Sternchen gucken\""}, {"kategorie": "", "text": "die Sternchen am Nachthimmel mit den Augen verfolgen"}]'::jsonb, ''),
  ('wueuesd-a-stereowaatschn-damits-bei-dia-in-olle-zwa-uan-gleichzeitig-klingld', 'Wüüsd a Stereowaatschn, damits bei dia in olle zwa Uan gleichzeitig klingld?', '', '', '', 'Wiener Gaunersprache', 'Willst du eine Stereowatschen, damit''s bei dir in beiden Ohren gleichzeitig klingelt?', '[{"kategorie": "wörtlich", "text": "\"Brauchst du einen Zweikanalschlag – damit''s bei dir in beiden Ohren gleichzeitig klingelt?\"  2. Willst du Dolby Surround auf die Backen – damit dir beide Trommelfelle gleichzeitig reißen?  3. Willst du eine Stereowatsche - damit dir gleich zwei Glocken gleichzeitig läuten?"}]'::jsonb, ''),
