  ('du-muassd-eam-schdessn-sunst-woadst-ewich-auf-dei-goeoed', 'Du muassd eam schdessn, sunst woadst ewich auf dei Gööd!', '', '', '', '', 'Du musst ihn anstoßen, sonst wartest du ewig auf dein Geld!', '[{"kategorie": "", "text": "Du musst Druck auf ihn machen, sonst wartest du ewig auf dein Geld!  2. Du musst ihm auf die Pelle rücken, sonst zahlt er nie!"}]'::jsonb, ''),
  ('du-muassd-eam-schdupfn-sunst-woadst-ewich-auf-dei-goeoed', 'Du muassd eam schdupfn, sunst woadst ewich auf dei Gööd!', '', '', '', '', 'Du musst ihn stupfen, sonst wartest du ewig auf dein Geld!', '[{"kategorie": "", "text": "Du musst Druck auf ihn machen, sonst wartest du ewig auf dein Geld!  2. Du musst ihm auf die Pelle rücken, sonst zahlt er nie!"}]'::jsonb, ''),
  ('wem-an-schdessa-geem', 'wem an Schdessa geem', '', '', '', '', 'jemandem einen Stößer geben', '[{"kategorie": "wörtlich", "text": "jemandem einen Stoß versetzen"}, {"kategorie": "fig.", "text": "jemandem auf die Pelle rücken, jemanden zu etwas drängen (Geldzahlung, etc.)"}]'::jsonb, ''),
  ('foa-ma-eia-gnoodn', 'Foa ma, eia Gnoodn!', '', '', '', '', 'Fahren wir, euer Gnaden!', '[{"kategorie": "wörtlich", "text": "\"Fahren wir, Euer Hochwohlgeboren!\"  2. \"Steigen Sie zu, Euer Hochwohlgeboren!\"  3. Steigen Sie in meinen Wagen, werter Herr! (freundliche Aufforderung des Fiakers an potentielle Fahrgäste, doch bitte in seine Kutsche zu steigen)"}]'::jsonb, ''),
  ('haum-eia-gnoodn-woi-geruud', 'Haum eia Gnoodn woi geruud?', '', '', '', '', 'Haben euer Gnaden wohl geruht?', '[{"kategorie": "wörtlich, Höflichkeitsbekundung von Dienern gegenüber Adeligen", "text": "\"Haben Euer Hochwohlgeboren angenehm geruht?\"  2. (scherzhafte Unterwürfigkeitsbekundung): \"Haben Sie gut geschlafen, mein Herr?\""}]'::jsonb, ''),
  ('eia-gnoodn', 'Eia Gnoodn!', '', '', '', '', 'Euer Gnaden!', '[{"kategorie": "wörtlich", "text": "\"Euer Hochwohlgeboren\", \"Eure Durchlaucht\" (Höflichkeitsanrede gegenüber Adeligen)"}, {"kategorie": "scherzhafte Unterwürfigkeitsbekundung gegenüber Fiakern, Kellnern und sonstigen Gleichgestellten", "text": "\"Hätten Sie bitte die Freundlichkeit?\";  \"Wären Sie so nett?;  \"Hätten Sie bitte die Güte?"}]'::jsonb, ''),
  ('des-fleisch-hod-an-schdich', 'Des Fleisch hod an Schdich!', '', '', '', '', 'Das Fleisch hat einen Stich!', '[{"kategorie": "", "text": "Das Fleisch ist ranzig!  2. Das Fleisch riecht/schmeckt ranzig!  3. Das Fleisch ist schon leicht verdorben!"}]'::jsonb, ''),
  ('des-hod-an-schdich-ins-goeoebliche', 'Des hod an Schdich ins Gööbliche!', '', '', '', '', 'Das hat einen Stich ins Gelbliche!', '[{"kategorie": "", "text": "Das hat einen gelblichen Farbton!  2. Das hat einen Hauch von Gelb!  3. Das tendiert ins Gelbe!"}]'::jsonb, ''),
  ('kan-schdich-mochn', 'kan Schdich mochn', '', '', '', '', 'keinen Stich machen', '[{"kategorie": "wörtlich", "text": "\"keinen Kartenstich machen\""}, {"kategorie": "fig.", "text": "keinen Treffer landen, keinen Erfolg haben, kläglich scheitern, leer ausgehen"}, {"kategorie": "scherzhaft für", "text": "bei jemandem keine Chance haben, \"keinen [[Fahrer]] machen\", \"nicht zum Einlochen kommen\", ohne [[Bumserl]] schlafen gehen"}]'::jsonb, ''),
  ('an-schdich-mochn', 'an Schdich mochn', '', '', '', '', 'einen Stich machen', '[{"kategorie": "wörtlich, Kartenspielerjargon", "text": "\"einen Kartenstich machen\""}, {"kategorie": "fig.", "text": "einen Treffer landen, Erfolg haben, den Vogel abschießen"}, {"kategorie": "scherzhaft für", "text": "Liebe machen, eine Nummer schieben, ein \"Bumserchen\" machen, einen [[Fahrer]] machen"}]'::jsonb, ''),
  ('dea-hod-in-sein-leben-no-nii-an-schdich-gmocht', 'Dea hod in sein Leben no nii an Schdich gmocht!', '', '', '', '', 'Der hat noch nie in seinem Leben einen Stich gemacht!', '[{"kategorie": "allg.", "text": "Der hat noch nie in seinem Leben Erfolg gehabt!  2. (scherzhaft): Der hat noch nie in seinem Leben eine Frau [[gepudert]]!"}]'::jsonb, ''),
  ('schdiifae-putzn', 'Schdiifä putzn', '', '', '', 'Wiener Sprüche, die sitzen!', 'Stiefel putzen', '[{"kategorie": "wörtlich", "text": "\"jemandes Stiefel putzen\""}, {"kategorie": "allg.", "text": "\"jemandem Knechtsdienste leisten\""}, {"kategorie": "", "text": "jemandem die Stiefel lecken"}, {"kategorie": "", "text": "sich unterwürfig verhalten, vor jemandem kriechen"}]'::jsonb, ''),
  ('schdiifaeputzn-is-ned-jedamaunns-soch', 'Schdiifäputzn is ned jedamaunns Soch!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Stiefelputzen ist nicht jedermanns Sache!', '[{"kategorie": "wörtlich", "text": "\"Es ist nicht jedermanns Sache, anderen die Stiefel zu putzen!\"  2. Nicht jeder ist zum Stiefelputzer geboren!  3. Nicht jeder macht sich gern klein für andere!  4. Nicht jeder wirft sich vor anderen unterwürfig auf die Knie!"}]'::jsonb, ''),
  ('do-ziagds-an-de-schdiifaen-aus', 'Do ziagds an de Schdiifän aus!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Da zieht es einem die Stiefel aus!', '[{"kategorie": "wörtlich", "text": "Das reißt dir glatt die Stiefel von den Füßen!  2. Das haut dir die Nägel aus den Sohlen!  3. Da bleibt dir glatt die Luft weg!  4. [[Do hauds da de Bootschn weg!]]"}]'::jsonb, ''),
  ('do-ziagds-da-de-schuach-aus', 'Do ziagds da de Schuach aus!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Da zieht es dir die Schuhe aus!', '[{"kategorie": "wörtlich", "text": "Da reißt es dir glatt die Schuhe von den Füßen!  2. Da haut es dir die Nägel aus den Sohlen!  3. Da bleibt dir glatt die Luft weg!  4. [[Do hauds da de Bootschn weg!]]"}]'::jsonb, 'Do hauds da de Bootschn weg!'),
  ('do-hauds-da-de-bootschn-weg', 'Do hauds da de Bootschn weg!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Da haut es dir die Patschen weg!', '[{"kategorie": "wörtlich", "text": "Da reißt es dir glatt die Pantoffel von den Füßen!  2. Da haut es dir die Nägel aus den Sohlen!  3. Da bleibt dir glatt die Luft weg!  4. [[Do ziagds da de Schuach aus!]]"}]'::jsonb, 'Do ziagds an de Schdiifän aus!'),
  ('dea-mochd-sein-eiganan-schdiifae', 'Dea mochd sein eiganan Schdiifä!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der macht seinen eigenen Stiefel!', '[{"kategorie": "wörtlich", "text": "\"Der macht sein eigenes Ding!\"  2. Der tanzt nach seiner eigenen Pfeife!  3. Der geht seinen  eigenen Weg!  4. Der macht, wie es ihm passt - und nicht wie die Leute wollen!"}]'::jsonb, ''),
  ('dea-hod-si-an-gscheidn-schdiifae-autrunkn', 'Dea hod si an gscheidn Schdiifä autrunkn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der hat sich einen gescheiten Stiefel angetrunken!', '[{"kategorie": "wörtlich", "text": "\"Der hat sich einen ordentlichen Rausch angesoffen!\"  2. Der hat so viele Stiefelgläser Bier getrunken, bis er voll war wie ein Tank!  3. Der hat mehr getrunken als zehn Stiefelkrüge hergeben!  4. Der hat sich komplett abgeschossen!"}]'::jsonb, ''),
  ('do-hoda-an-uandlichn-schdiifae-zsaummbaud', 'Do hoda an uandlichn Schdiifä zsaummbaud!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Da hat er einen ordentlichen Stiefel zusammengebaut!', '[{"kategorie": "wörtlich", "text": "\"Da hat er einen gehörigen Murks produziert!\"  2. Da hat er ordentlich Mist gebaut!  3. Da hat er einen Schuss in den Ofen hingelegt!"}]'::jsonb, ''),
  ('dea-schdeed-komplett-untan-schdiifae-von-seina-oidn', 'Dea schdeed komplett untan Schdiifä von seina Oidn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der steht komplett unter dem Stiefel von seiner Alten!', '[{"kategorie": "wörtlich", "text": "\"Der steht komplett unter dem Stiefel seiner Frau!\"  2. Er lässt sich willenlos von seiner Frau herumkommandieren!  3. Der tanzt komplett nach der Pfeife seiner Frau!"}]'::jsonb, ''),
  ('an-schdiifae-zsaummreedn', 'an Schdiifä zsaummreedn', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen Stiefel zusammenreden', '[{"kategorie": "wörtlich", "text": "\"dummes Zeug reden\""}, {"kategorie": "", "text": "nur [[Schmonzes]] von sich geben"}, {"kategorie": "", "text": "Unsinn schwatzen"}, {"kategorie": "", "text": "an [[Quargl]] dazöön"}]'::jsonb, ''),
  ('an-schdiifae-vatroong', 'an Schdiifä vatroong', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'einen Stiefel vertragen', '[{"kategorie": "wörtlich", "text": "\"einen Stiefelkrug vertragen\""}, {"kategorie": "", "text": "viel Alkohol vertragen, ohne betrunken zu werden"}, {"kategorie": "", "text": "äußerst trinkfest sein"}]'::jsonb, ''),
  ('dea-vatroogd-an-schdiifae-und-hod-a-leewa-wiara-paunza', 'Dea vatroogd an Schdiifä und hod a Leewa wiara Paunza!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der verträgt einen Stiefel und hat eine Leber wie ein Panzer!', '[{"kategorie": "wörtlich", "text": "\"Der verträgt Unmengen von Alkohol und hat eine Leber wie ein Panzer!\"  2. Der steckt jeden Rausch weg, als wär’s Wasser!  3. Der kann saufen wie ein Loch und steht trotzdem wie ein Leuchtturm!"}]'::jsonb, ''),
  ('auf-ka-kuahaud-gee', 'auf ka Kuahaud gee', '', '', '', 'Wiener Sprüche, die sitzen!', 'auf keine Kuhhaut gehen', '[{"kategorie": "wörtlich", "text": "\"nicht auf eine Kuhhaut passen\" (Zur Erklärung: Im Mittelalter glaubte man, der Teufel würde die Sünden der Menschen auf Pergament, also auf Tierhaut, aufschreiben, um sie den Seelen am Tag des Jüngsten Gerichts vorzuhalten)"}, {"kategorie": "fig.", "text": "\"nicht hinnehmbar sein\""}, {"kategorie": "", "text": "jedes annehmbare Maß übersteigen"}, {"kategorie": "", "text": "jenseits von Gut und Böse sein"}]'::jsonb, ''),
  ('wos-dea-scho-wiida-fiaran-schdiifae-zsaummreed-des-geed-auf-ka-kuahaud', 'Wos dea scho wiida fiaran Schdiifä zsaummreed, des geed auf ka Kuahaud!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Was der schon wieder für einen Stiefel zusammenredet, das geht auf keine Kuhhaut!', '[{"kategorie": "wörtlich", "text": "\"Was der schon wieder für einen Unsinn verzapft, das geht auf keine Kuhhaut!\"  2. Was der schon wieder für einen Blödsinn redet, ist nicht mehr auszuhalten!  3. Was der schon wieder für einen Unsinn zusammenredet, ist jenseits von Gut und Böse!"}]'::jsonb, ''),
  ('an-schdiifae-mochn', 'an Schdiifä mochn', '', '', '', '', 'einen Stiefel machen', '[{"kategorie": "", "text": "einen Fehler machen"}, {"kategorie": "", "text": "einen [[Patzer]] begehen"}, {"kategorie": "", "text": "einen Schnitzer machen"}]'::jsonb, ''),
  ('ea-woond-auf-da-zeenaschdiang', 'Ea woond auf da Zeenaschdiang!', '', '', '', '', 'Er wohnt auf der Zehnerstiege!', '[{"kategorie": "", "text": "Er wohnt im Haus Nr. 10"}, {"kategorie": "", "text": "Er wohnt im Flügeltrakt mit der Nummer 10!  (Zur Erkärung: Große Wohnhausanlagen [[[Gemeindebauten]]] haben in Wien nur eine Hausnummer, sodass die Zugänge zu den einzelnen Flügeltrakten durch eigene \"Stiegennummern\" [Treppenhausnummern] gekennzeichnet sind)"}]'::jsonb, ''),
  ('zu-dera-hockn-weama-scho-no-an-schdueue-finden', 'Zu dera Hockn weama scho no an Schdüü finden!', '', '', '', '', 'Zu dieser Hacken werden wir schon noch einen Stiel finden', '[{"kategorie": "", "text": "Diesen Job werden wir schon irgendwie meistern!  2. Diesen Job werden wir schon irgendwie hinbekommen!"}]'::jsonb, ''),
  ('da-sektkoeoech-hod-an-vue-z-dinnan-schdueue', 'Da Sektkööch hod an vü z''dinnan Schdüü!', '', '', '', '', 'Der Sektkelch hat einen viel zu dünnen Stiel!', '[{"kategorie": "", "text": "Der Stiel des Sektglases ist viel zu zierlich!  2. Der Stiel des Sektkelchs ist viel zu filigran!"}]'::jsonb, ''),
  ('do-geed-an-s-schdifdl-aus', 'Do geed an s''Schdifdl aus!', '', '', '', '', 'Da geht einem das Stiftl aus!', '[{"kategorie": "", "text": "Da platzt einem der Kragen!  2. Da geht einem der Hut hoch!"}]'::jsonb, ''),
  ('dea-is-no-imma-schdingad-auf-mi', 'Dea is no imma schdingad auf mi!', '', '', '', '', 'Der ist noch immer stinkert auf mich!', '[{"kategorie": "", "text": "Der ist noch immer angefressen auf mich!  2. Der ist noch immer stinksauer auf mich!  3. Der kann mich nicht riechen!"}]'::jsonb, ''),
  ('schdingad-wean', 'schdingad wean', '', '', '', '', 'stinkert werden', '[{"kategorie": "wörtlich", "text": "\"stinkig werden\""}, {"kategorie": "", "text": "wütend werden, ungut werden"}]'::jsonb, ''),
  ('des-fleisch-is-uns-schdingad-wuan', 'Des Fleisch is uns schdingad wuan!', '', '', '', '', 'Das Fleisch ist uns stinkert geworden!', '[{"kategorie": "", "text": "Das Fleisch ist uns schlecht geworden!  2. Das Fleisch ist uns verdorben!"}]'::jsonb, ''),
  ('du-schdingada-praesa-in-da-wenediga-au', 'Du schdingada Präsa in da Wenediga Au!', '', '', '', '', 'Du stinkendes Präservativ in der Venediger Au!', '[{"kategorie": "", "text": "Du stinkst wie ein entsorgtes Präservativ in der Venediger Au!  2. Du stinkst wie ein weggeworfenes Kondom in der Venediger Au!  (\"Venediger Au\" =  Straßenstrich im Wiener Prater [jener Teil der Wiener Praterauen, in dem Gunstgewerblerinnen auf den Strich gehen])"}]'::jsonb, ''),
