  ('vom-schdockal-foin', 'vom Schdockal foin', '', '', '', '', 'vom Stockerl fallen', '[{"kategorie": "wörtlich", "text": "\"vom Hocker fallen\""}, {"kategorie": "", "text": "sprachlos sein, komplett von den Socken sein, [[aus]] den Schlapfen kippen, [[aus]] de Bock foin"}]'::jsonb, ''),
