  ('schlechd-gschdoppaed-haum', 'schlechd gschdoppäd haum', '', '', '', '', 'schlecht gestoppelt haben', '[{"kategorie": "wörtlich", "text": "\"schlecht gestollt haben\""}, {"kategorie": "Fußballerjargon", "text": "mit falschen [[Stollen]] spielen (mit Fußballschuhen spielen, deren Stollen für die herrschenden Platzverhältnisse nicht geeignet sind)"}]'::jsonb, ''),
  ('duat-wos-min-schdoppaeziaga-de-eadaepfaen-ausgroom', 'duat wos min Schdoppäziaga de Eadäpfän ausgroom', '', '', '', '', 'dort, wo sie mit dem Stoppelzieher die Erdäpfel ausgraben', '[{"kategorie": "", "text": "am Arsch der Welt, in der hintersten Provinz"}]'::jsonb, ''),
  ('kiidreal', 'Kììdreal', '', '', '', '', 'Kittröhrl', '[{"kategorie": "wörtlich", "text": "\"Kittröhrchen\" (Determinativkompositum aus \"Kitt\"=\"Fensterkitt\" und \"Röhrl\"=\"Röhrchen\")"}, {"kategorie": "", "text": "Blasröhrchen für Kittkügelchen, \"Kugelspucker\" (Lausbubenspielzeug)"}]'::jsonb, ''),
  ('gee-wia-da-schdoach-im-solood', 'gee wia da Schdoach im Solood', '', '', '', '', 'gehen wie der Storch im Salat!', '[{"kategorie": "wörtlich", "text": "\"gestelzt wie ein Storch gehen\""}, {"kategorie": "", "text": "gekünstelt herumstelzen, gespreizt herumstaksen"}]'::jsonb, ''),
  ('ka-marii-ka-quatia-kaane-schnoeoen-finga-den-dippaebruada-kaunnst-ned-amoi-schdoeoen-schickn', 'Ka Marii, ka Quatia, kaane schnöön Finga - den Dippäbruada kaunnst ned amoi schdöön schickn!', '', '', '', 'Wiener Gaunersprache', 'Keine Marie, kein Quartier, keine schnellen Finger – den Tippelbruder kannst du nicht einmal stehlen schicken!', '[{"kategorie": "wörtlich", "text": "\"Kein Zaster, kein Quartier, keine schnellen Finger – diesen Obdachlosen kannst du nicht einmal stehlen schicken!\"  2. Kein Geld, kein Dach über’m Kopf, kein Talent – aus diesem Herumstreuner machst du nicht mal ’nen Taschendieb!  3. Ohne Knete, ohne Hütte, ohne schnelles Händchen – der taugt für gar nichts, nicht mal fürs Gaunergeschäft!"}]'::jsonb, ''),
  ('da-dippaebruada-is-mid-an-leichdn-binkl-und-an-schwean-weakzeigguat-duachs-laund-zoong-imma-auf-da-joogd-noch-ana-ealichn-hockn', 'Da Dippäbruada is mid an leichdn Binkl und an schwean Weakzeigguat duachs Laund zoong, imma auf da Joogd noch ana ealichn Hockn!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Der Tippelbruder zog mit leichtem Binkel und schwerem Werkzeuggurt durch das Land, immer auf der Jagd nach einer ehrlichen Hacken!', '[{"kategorie": "wörtlich", "text": "\"Der fahrende Geselle zog mit leichtem Bündel und schwerem Werkzeuggurt durch das Land, immer auf der Suche nach ehrlicher Arbeit!\"  2. Mit seinem schlichten Bündel und dem Werkzeuggurt um die Hüften zog der fahrende Geselle von Ort zu Ort – auf der Suche nach redlichem Tagwerk!  3. Der Tippelbruder trug nicht viel – nur sein Bündel, den Gürtel voll Eisen und den Willen zu ehrlichem Handwerk!"}]'::jsonb, ''),
  ('mei-dippaebruada-schbueuet-oft-drei-naechte-hintaranaunda-ohne-pause-duach', 'Mei Dippäbruada schbüüt oft drei Nächte hintaranaunda ohne Pause duach!', '', '', '', 'Wiener Kartentipplerjargon', 'Mein Tippelbruder spielt oft drei Nächte hintereinander ohne Pause durch!', '[{"kategorie": "wörtlich", "text": "\"Mein Zockerkollege spielt oft drei Nächte hintereinander ohne Pause durch!\"  2. Mein Mitspieler zockt oft drei Nächte durch, ohne sich auszuruhen!  3. Mein Kartenspielkollege zieht regelmäßig dreitägige Zocker-Sessions durch!"}]'::jsonb, ''),
  ('heit-haums-gschdraad', 'Heit haums gschdraad!', '', '', '', '', 'Heute haben sie gestreut!', '[{"kategorie": "", "text": "Heute haben sie Splitt auf den Gehweg gestreut!  2. Heute haben sie Streugut ausgebracht! (bei Glatteis)"}]'::jsonb, ''),
  ('es-is-gschdraad', 'Es is gschdraad!', '', '', '', '', 'Es ist gestreut', '[{"kategorie": "", "text": "Splitt wurde gestreut!  2. Streugut ist ausgebracht! (bei Glatteis)"}]'::jsonb, '')
